def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def one(text: str, old: str, new: str) -> str:
    if text.count(old) != 1:
        raise ValueError(f"Expected one match, found {text.count(old)}: {old[:100]}")
    return text.replace(old, new, 1)


def paragraph(text: str, prefix: str, new: str) -> str:
    found = [line for line in text.splitlines() if line.startswith(prefix)]
    if len(found) != 1:
        raise ValueError(f"Expected one paragraph {prefix}: {len(found)}")
    return one(text, found[0], new)


